# -*- coding: utf-8 -*-
import base64, io, zipfile
_DATA = ""

def materialize():
    root = __import__('pathlib').Path(__file__).resolve().parent / '.airbnb_sgphb3_10'
    root.mkdir(exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(_DATA))) as z:
        z.extractall(root)
    return [root / f'all_{i:02d}.jpeg' for i in range(1, 11)]
